// CloudtainerML rev0033 — Routing absorption sparse-gate wind tunnel.
// Synthetic screen inspired by Routing Absorption in Sparse Attention. Not a reproduction.
#include <bits/stdc++.h>
using namespace std;
static string q(const string&s){string o="\""; for(char c:s){ if(c=='"'||c=='\\') o+='\\'; if(c=='\n') o+="\\n"; else o+=c;} return o+'"';}
struct Regime{string name; double concentration, coadapt, rare, noise, mask_shift, cost_pressure; int seed;};
struct Row{string regime, method; double quality,cost,gate_f1,deployment_loss,absorption_gap,rare_miss,regret,score;};
static double clamp01(double x){return max(0.0,min(1.0,x));}
static double jitter(int seed, string m){ uint64_t h=1469598103934665603ULL; for(char c:m){h^=(unsigned char)c; h*=1099511628211ULL;} h ^= seed*0x9e3779b97f4a7c15ULL; return ((h%1000)/1000.0-0.5)*0.012;}
static Row eval(const Regime&r,const string&m){
 double base = 0.58 + 0.30*r.concentration - 0.18*r.noise - 0.08*r.mask_shift;
 double ql=0,cost=0,f1=0,deploy=0,absorb=0,rare=0;
 if(m=="dense_full"){ql=base+0.24-0.04*r.noise; cost=1.0; f1=1.0; deploy=0.0; absorb=0.0; rare=0.0;}
 else if(m=="oracle_sparse_mask"){ql=base+0.22-0.06*r.rare; cost=0.36; f1=1.0; deploy=0.02*r.mask_shift; absorb=0.0; rare=0.05*r.rare;}
 else if(m=="frozen_random_gate"){ql=base+0.05*r.coadapt-0.05*r.rare-0.03*r.noise; cost=0.33; f1=0.48+0.05*r.concentration; deploy=0.02+0.02*r.mask_shift; absorb=0.82*r.coadapt; rare=0.42*r.rare;}
 else if(m=="learned_gate_end2end"){ql=base+0.08+0.03*r.concentration-0.09*r.coadapt-0.06*r.mask_shift; cost=0.36; f1=0.72+0.16*r.concentration; deploy=0.12*r.coadapt+0.10*r.mask_shift; absorb=0.78*r.coadapt; rare=0.32*r.rare;}
 else if(m=="stochastic_gate_training"){ql=base+0.05+0.04*r.concentration-0.06*r.coadapt-0.03*r.noise; cost=0.40; f1=0.62+0.10*r.concentration; deploy=0.06+0.08*r.coadapt; absorb=0.52*r.coadapt; rare=0.26*r.rare;}
 else if(m=="distilled_gate_on_coadapted_qkv"){ql=base-0.16*r.coadapt-0.18*r.mask_shift+0.06*r.concentration; cost=0.34; f1=0.88+0.08*r.concentration; deploy=0.32*r.coadapt+0.30*r.mask_shift; absorb=0.95*r.coadapt; rare=0.34*r.rare;}
 else if(m=="posthoc_gate_fixed_qkv"){ql=base+0.15+0.03*r.concentration-0.04*r.rare; cost=0.38; f1=0.86+0.08*r.concentration; deploy=0.03+0.04*r.mask_shift; absorb=0.10*r.coadapt; rare=0.12*r.rare;}
 else if(m=="gate_plus_dense_escape"){ql=base+0.16-0.02*r.mask_shift; cost=0.46+0.12*r.rare; f1=0.82; deploy=0.04; absorb=0.18*r.coadapt; rare=0.06*r.rare;}
 ql=clamp01(ql+jitter(r.seed,m)); cost=max(0.05,cost); f1=clamp01(f1); deploy=max(0.0,deploy); absorb=clamp01(absorb); rare=clamp01(rare);
 double score=(1.0-ql)+0.35*cost*r.cost_pressure+0.38*deploy+0.22*rare+0.16*absorb-0.08*f1;
 return {r.name,m,ql,cost,f1,deploy,absorb,rare,0,score};
}
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0033_ROUTING_ABSORPTION_GATE_SMOKE.json"; vector<Regime> regs={{"concentrated_mask_easy",0.92,0.12,0.10,0.06,0.08,0.55,1},{"coadaptation_pressure",0.75,0.92,0.18,0.08,0.26,0.70,2},{"rare_route_tokens",0.65,0.55,0.92,0.12,0.18,0.80,3},{"mask_distribution_shift",0.70,0.72,0.26,0.14,0.88,0.75,4},{"noisy_uniform_attention",0.22,0.62,0.34,0.55,0.34,0.90,5},{"low_cost_decoding",0.80,0.78,0.30,0.10,0.22,1.20,6}}; vector<string> methods={"dense_full","oracle_sparse_mask","frozen_random_gate","learned_gate_end2end","stochastic_gate_training","distilled_gate_on_coadapted_qkv","posthoc_gate_fixed_qkv","gate_plus_dense_escape"}; vector<Row> rows; map<string,int>winners, nonoracle; for(auto&r:regs){ vector<Row> cand; for(auto&m:methods)cand.push_back(eval(r,m)); double best=1e9; for(auto&x:cand) best=min(best,x.score); for(auto&x:cand) x.regret=max(0.0,x.score-best); auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[b->method]++; auto no=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){ if(a.method=="oracle_sparse_mask")return false; if(b.method=="oracle_sparse_mask")return true; return a.score<b.score;}); nonoracle[no->method]++; rows.insert(rows.end(),cand.begin(),cand.end()); }
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0033\",\n  \"probe\": \"routing_absorption_gate\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Learned gates only help in this toy when their representations are decoupled or allowed dense escape; coadaptation regimes make frozen random gates annoyingly competitive.\",\n    \"screen_regret_fields\": [\"deployment_loss\", \"absorption_gap\", \"rare_miss\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"quality\": "<<r.quality<<", \"cost\": "<<r.cost<<", \"gate_f1\": "<<r.gate_f1<<", \"deployment_loss\": "<<r.deployment_loss<<", \"absorption_gap\": "<<r.absorption_gap<<", \"rare_miss\": "<<r.rare_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n");} f<<"  ]\n}\n"; }
